css:
.a3a{font-size:11.5px;line-height:1.55}
.a3a p{margin:0 0 9px;text-align:justify}
.a3a ol{margin:0 0 12px 20px;padding:0}
.a3a ol li{margin-bottom:8px;text-align:justify}
.a3a h2{font-size:14px;margin:0 0 12px;text-align:center;text-transform:uppercase;letter-spacing:.04em}
.a3a h3{font-size:12px;margin:16px 0 6px;font-weight:600}
.a3a table.sch{width:100%;border-collapse:collapse;margin-bottom:12px;font-size:11px}
.a3a table.sch th,.a3a table.sch td{border:1px solid #666;padding:6px 8px;vertical-align:top;text-align:left}
.a3a table.sch th{width:45%;background:#f2f2f2;font-weight:600}
.a3a table.sch.wheel th{width:25%;text-align:center}
.a3a table.sch.wheel td{height:24px}
/* Three rows and a header: small enough to keep whole, and it reads as one thing. */
.a3a table.sch.wheel{page-break-inside:avoid}
.a3a table.sig{width:100%;margin-top:34px;border:0}
.a3a table.sig td{width:50%;border:0;padding:0 14px 0 0;vertical-align:top}
.a3a table.sig p{margin:0 0 10px;text-align:left}
.a3a .party{font-weight:600}
.a3a .who{font-size:10.5px;color:#444}
.a3a .stamp{margin-top:18px;font-size:10.5px;color:#444;font-style:italic}
.a3a .warn{border-left:3px solid #b00;padding:8px 10px;background:#fdf3f3}
/* not `.page-break`: Frappe's own print stylesheet defines that as page-break-AFTER,
   so an element carrying it would break on both sides and leave a blank page. */
.a3a .a3a-break{page-break-before:always;margin-top:0}
